'use strict';
const KEY='lastro-v3',E=Ledger,FIAT=['BRL','USD'],ASSETS=['BTC','ETH','SOL','USDC','USDT','BNB','BRL','USD'];
const catalog={BTC:{name:'Bitcoin',icon:'₿',css:''},ETH:{name:'Ethereum',icon:'Ξ',css:'eth'},SOL:{name:'Solana',icon:'◎',css:'sol'},USDC:{name:'USD Coin',icon:'$',css:'eth'},USDT:{name:'Tether',icon:'₮',css:'sol'},BNB:{name:'BNB',icon:'◈',css:''},BRL:{name:'Real',icon:'R$',css:'sol'},USD:{name:'Dólar',icon:'$',css:'eth'}};

const types={OPENING:'Saldo inicial',BUY:'Compra',SELL:'Venda',CONVERT:'Conversão',DEPOSIT:'Aporte',WITHDRAW:'Retirada',TRANSFER:'Transferência',TAX:'Imposto pago'};
const cl=x=>JSON.parse(JSON.stringify(x));
function demoEvent(id,type,date,asset,qty,other={}){return{id:'demo'+id,sequence:id,date,owner:'Jaime (demo)',venue:'Binance',country:'UNKNOWN',type,asset,qty,price:0,quote:'BRL',fx:1,feeQty:0,feeCurrency:'BRL',feeFx:1,notes:'Exemplo fictício',reference:'DEMO-'+id,...other}}
const seed={version:3,owners:['Jaime (demo)','Eliane (demo)'],scenario:'mixed',events:[
 demoEvent(1,'OPENING','2026-01-01T09:00','USDC',10000,{costBRL:50000}),
 demoEvent(2,'DEPOSIT','2026-01-02T09:00','BRL',5000),
 demoEvent(3,'BUY','2026-08-10T10:00','BTC',.05,{price:76000,quote:'USDC',fx:5,feeQty:3.8,feeCurrency:'USDC',feeFx:5}),
 demoEvent(4,'BUY','2026-08-15T10:00','ETH',1,{price:2800,quote:'USDC',fx:5,feeQty:2.8,feeCurrency:'USDC',feeFx:5}),
 demoEvent(5,'BUY','2026-09-01T10:00','SOL',10,{price:140,quote:'USDC',fx:5.05,feeQty:1.4,feeCurrency:'USDC',feeFx:5.05}),
 demoEvent(6,'SELL','2026-09-15T10:00','BTC',.02,{price:85000,quote:'USDC',fx:5.1,feeQty:1.7,feeCurrency:'USDC',feeFx:5.1}),
 demoEvent(7,'SELL','2026-10-10T10:00','ETH',.25,{price:2500,quote:'USDC',fx:5.2,feeQty:.625,feeCurrency:'USDC',feeFx:5.2}),
 demoEvent(8,'TRANSFER','2026-10-15T10:00','BTC',.01,{toVenue:'Carteira própria',feeQty:.00001,feeCurrency:'BTC',feeFx:400000}),
 demoEvent(9,'TAX','2026-10-20T10:00','BRL',120,{taxSource:'external',taxPeriod:'2026-09',reference:'DEMO-RECIBO',notes:'Valor informado para demonstrar o registro; não calculado pelo app.'}),
 demoEvent(10,'OPENING','2026-01-01T09:00','USDC',4000,{owner:'Eliane (demo)',costBRL:20000}),
 demoEvent(11,'BUY','2026-09-10T10:00','BTC',.02,{owner:'Eliane (demo)',price:75000,quote:'USDC',fx:5.1,feeQty:1.5,feeCurrency:'USDC',feeFx:5.1})
],plans:{},reviews:[],reconciliations:[]};
let state=cl(seed),recovery=false;function check(s){if(!s||s.version!==3||!Array.isArray(s.events)||!Array.isArray(s.owners)||!s.owners.length||s.owners.some(o=>typeof o!=='string'||!o.trim()||o.includes('|'))||!s.plans||typeof s.plans!=='object'||!Array.isArray(s.reviews)||typeof s.scenario!=='string')throw Error('Backup incompatível com a v3.');if(s.events.some(e=>!s.owners.includes(e.owner)))throw Error('Titular de operação ausente do cadastro.');for(const [key,p] of Object.entries(s.plans)){if(!p||!['stop','target','partial','maxRisk'].every(k=>Number.isFinite(p[k]))||p.stop<=0||p.target<=p.stop||p.partial<=0||p.partial>100||p.maxRisk<=0||p.maxRisk>100||typeof p.reason!=='string')throw Error('Estratégia inválida no backup.');}if(s.reviews.some(x=>!x||typeof x.key!=='string'||typeof x.decision!=='string'||!Number.isFinite(x.price)))throw Error('Revisão inválida no backup.');if(s.reconciliations!==undefined&&!Array.isArray(s.reconciliations))throw Error('Conferências inválidas.');for(const c of s.reconciliations||[]){if(!s.owners.includes(c.owner))throw Error('Titular da conferência ausente.');E.compareBalance(s.events,c);}E.replay(s.events);return s}try{const r=localStorage.getItem(KEY);if(r)state=check(JSON.parse(r))}catch{recovery=true}
let chartView='columns';
let page='overview',owner='all',start='2026-01-01',end='2026-10-31',selected='',query='',typeFilter='all';
const $=id=>document.getElementById(id),app=$('app'),modal=$('modal'),form=$('form');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=2)=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}),brl=v=>'R$ '+n(v),qty=v=>Number(v).toLocaleString('pt-BR',{maximumFractionDigits:8}),percent=v=>n(v)+'%',signed=v=>(v>0?'+':'')+brl(v),pk=h=>h.owner+'|'+h.asset;

function report(o=owner){return E.replay(state.events,{owner:o,end})}function positions(r=report()){return E.value(r,r.marks)}function total(r=report()){return positions(r).reduce((s,h)=>s+h.value,0)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Armazenamento indisponível: exporte o backup antes de fechar.')}}let timer;function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',4000)}
function pill(t,c='green'){return `<span class="pill ${c==='green'?'':c}"><i class="signal-dot"></i>${esc(t)}</span>`}function button(t,a,primary=false,more=''){return `<button class="btn ${primary?'primary':''}" data-action="${a}" ${more}>${t}</button>`}function textbtn(t,a,more=''){return `<button class="textbtn" data-action="${a}" ${more}>${t}</button>`}
const compactHelpLabels=new Set(['Custo dos saldos','Resultado realizado','Taxas das operações','Operações no período','Total vendido','Custo vendido','Taxas','Imposto pago','Câmbio histórico','Custo da operação','Diferença de quantidade','Valor de referência']);
function info(label,text){if(!compactHelpLabels.has(label))return '';return `<button type="button" class="info-button" aria-label="Informações: ${esc(label)}" data-help="${esc(text)}"><span aria-hidden="true">i</span></button>`}
function installHelp(){
 const pop=document.createElement('div');pop.id='lastro-help';pop.className='info-popover';pop.setAttribute('popover','manual');pop.setAttribute('role','tooltip');document.body.append(pop);
 let active=null,closeTimer;
 const hide=()=>{clearTimeout(closeTimer);if(active){active.removeAttribute('aria-describedby');active=null;}if(pop.matches(':popover-open'))pop.hidePopover();};
 const open=b=>{clearTimeout(closeTimer);const host=modal.open?modal:document.body;if(pop.parentElement!==host){if(pop.matches(':popover-open'))pop.hidePopover();host.append(pop);}if(active&&active!==b)active.removeAttribute('aria-describedby');active=b;pop.textContent=b.dataset.help.replaceAll('{DATA}',end.split('-').reverse().join('/'));b.setAttribute('aria-describedby',pop.id);if(!pop.matches(':popover-open'))pop.showPopover();const rect=b.getBoundingClientRect(),width=Math.min(330,window.innerWidth-24);pop.style.width=width+'px';pop.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12))+'px';const h=pop.getBoundingClientRect().height;pop.style.top=(rect.bottom+h+12<window.innerHeight?rect.bottom+8:Math.max(12,rect.top-h-8))+'px';};
 document.addEventListener('pointerover',e=>{const b=e.target.closest('.info-button');if(b)open(b);});
 document.addEventListener('pointerout',e=>{if(e.target.closest('.info-button')&&active!==document.activeElement)closeTimer=setTimeout(hide,180);});
 pop.addEventListener('pointerenter',()=>clearTimeout(closeTimer));pop.addEventListener('pointerleave',hide);
 document.addEventListener('focusin',e=>{const b=e.target.closest('.info-button');if(b)open(b);else hide();});
 document.addEventListener('click',e=>{const b=e.target.closest('.info-button');if(b){e.preventDefault();e.stopImmediatePropagation();open(b);}else if(!pop.contains(e.target))hide();},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();e.stopImmediatePropagation();hide();}},true);
 window.addEventListener('scroll',hide,true);window.addEventListener('resize',hide);modal.addEventListener('close',hide);
 // Only compact metric cards move their long explanation into a tooltip.
 const tidy=()=>{app.querySelectorAll('.metric').forEach(card=>{const note=card.querySelector('small'),label=card.querySelector('.eyebrow');if(note&&label){label.insertAdjacentHTML('beforeend',info(label.textContent,note.textContent));note.remove();}});};
 new MutationObserver(tidy).observe(app,{childList:true,subtree:true});tidy();
}

function head(t,s,a=''){return `<div class="head"><div><h1>${t}</h1><p class="sub">${s}</p></div><div class="actionsbar">${a}</div></div>`}function moneyClass(v){return v< -E.EPS?'negative':v>E.EPS?'up':''}
function coin(h){const c=catalog[h.asset]||{name:h.asset,icon:h.asset.slice(0,1),css:'sol'};return `<div class="asset"><span class="coin ${c.css}">${esc(c.icon)}</span><div><b>${esc(h.asset)}</b><small>${esc(h.owner)}</small></div></div>`}
function go(p){page=p;render();window.scrollTo(0,0)}function openHolding(key){selected=key;go('detail')}
function metrics(r){const s=E.period(r,start,end),cost=r.holdings.reduce((sum,h)=>sum+h.cost,0);return `<div class="metrics focus-metrics">${[['Custo dos saldos',brl(cost),'Custo de aquisição dos ativos e moedas que você ainda possui até a data Até, incluindo taxas elegíveis. Não é valor de mercado.'],['Resultado realizado',signed(s.realized),'Resultados das operações no período, incluindo câmbio e rede. Taxas já consideradas; imposto pago não descontado. Clique em Ver composição para rastrear cada parcela.'],['Taxas das operações',brl(s.fees),'Taxas registradas no período, em reais. Elas já integram custo ou resultado e não devem ser descontadas novamente.'],['Operações no período',s.count,'Compras, vendas e conversões no período. Não inclui aportes, retiradas e transferências.']].map(([label,value,hint])=>`<div class="card metric"><span class="eyebrow">${label}</span><strong>${value}</strong><small>${hint}</small></div>`).join('')}</div>`}
function holdingsTable(r){const hs=positions(r);return `<div class="card bottom"><div class="row wrap"><h2>Saldos e custos ${info('Referências de valor','Quantidade e preço médio vêm do histórico. O valor usa a última cotação registrada nas operações até a data Até, não uma cotação de mercado atual. O custo é separado por titular.')}</h2>${textbtn('Exportar saldos','exportHoldings')}</div><div class="tablewrap"><table><thead><tr><th>Ativo / titular</th><th>Quantidade</th><th>Preço médio</th><th>Custo do saldo</th><th>Valor de referência ${info('Valor de referência','Quantidade multiplicada pela última cotação registrada. Pode estar desatualizada e não representa um preço de venda disponível.')}</th><th>Diferença para o custo</th><th></th></tr></thead><tbody>${hs.map(h=>`<tr><td>${coin(h)}</td><td>${qty(h.qty)}</td><td>${brl(h.average)}</td><td>${brl(h.cost)}</td><td>${brl(h.value)}</td><td class="${moneyClass(h.unrealized)}">${signed(h.unrealized)}</td><td>${textbtn('Entender saldo','holdingDetail',`data-key="${esc(pk(h))}"`)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Registre um saldo inicial ou aporte para começar.</td></tr>'}</tbody></table></div></div>`}
function equityChart(r){
 const demo=false;
 let dates=[...new Set(r.rows.filter(e=>e.date.slice(0,10)>=start).map(e=>e.date.slice(0,10)))];
 if(r.rows.some(e=>e.date.slice(0,10)<start))dates.unshift(start);
 if(!dates.includes(end))dates.push(end);
 if(chartView==='columns'){
 dates=[];let cursor=new Date(start+'T12:00:00Z');cursor.setUTCDate(1);
 while(cursor.toISOString().slice(0,10)<=end&&dates.length<120){let next=new Date(cursor);next.setUTCMonth(next.getUTCMonth()+1);let close=new Date(next.getTime()-86400000).toISOString().slice(0,10);dates.push(close>end?end:close);cursor=next;}
 }
 dates.sort();
 let points=dates.map(d=>{let rr=E.replay(state.events,{owner,end:d}),mm=rr.marks;let value=E.value(rr,mm).reduce((s,h)=>s+h.value,0),capital=rr.initial.reduce((s,x)=>s+x.value,0)+rr.flows.reduce((s,x)=>s+x.value,0);

 return{date:d,value,capital};});
 const values=points.flatMap(p=>[p.value,p.capital]),actualLow=Math.min(...values),high=Math.max(...values,1),padding=Math.max((high-actualLow)*.18,high*.025,1);
 const min=Math.max(0,actualLow-padding),max=high+padding,span=max-min||1;
 const first=Date.parse(points[0]?.date||start),last=Date.parse(end),x=p=>40+(last===first?0:(Date.parse(p.date)-first)/(last-first))*570,y=v=>190-(v-min)/span*155;
 const xy=key=>points.map(p=>`${x(p)},${y(p[key])}`).join(' ');
 const area=points.length?`M${x(points[0])},190 L${points.map(p=>`${x(p)},${y(p.value)}`).join(' L')} L${x(points[points.length-1])},190 Z`:'';
 const controls=`<div class="chart-switch" role="group" aria-label="Visualização do gráfico">${['columns','lines'].map(v=>`<button class="textbtn" data-action="chartView" data-key="${v}" aria-pressed="${chartView===v}">${v==='columns'?'Colunas':'Linhas'}</button>`).join('')}</div>`;
 if(chartView==='columns'){
 const upper=Math.max(...points.map(p=>Math.max(p.capital,p.value)),1)*1.12,lower=Math.min(0,...points.map(p=>p.value-p.capital))*1.2,range=upper-lower,by=v=>205-(v-lower)/range*170,zero=by(0),step=560/Math.max(points.length,1),width=Math.min(34,step*.66);
 const short=v=>'R$ '+(Math.abs(v)>=1000?(v/1000).toLocaleString('pt-BR',{maximumFractionDigits:0})+' mil':n(v,0));
 const svg=`<svg class="equity-chart equity-bars" viewBox="0 0 660 255" role="img" aria-label="Referências mensais: capital e diferenças em reais">${[0,.25,.5,.75,1].map(t=>{let value=upper*(1-t),yy=by(value);return `<path d="M70 ${yy}H635" stroke="#e2e9ed"/><text x="62" y="${yy+3}" text-anchor="end" font-size="10" fill="#82939a">${short(value)}</text>`}).join('')}<path d="M70 ${zero}H635" stroke="#9cabb2"/>${points.map((p,i)=>{const xx=75+i*step+(step-width)/2,gain=p.value-p.capital;return `<g><title>${p.date}: capital ${brl(p.capital)}; ${gain<0?'perda':'ganho'} ${signed(gain)}; patrimônio ${brl(p.value)}${demo?' (simulado)':''}</title><rect x="${xx}" y="${Math.min(by(p.capital),zero)}" width="${width}" height="${Math.abs(by(p.capital)-zero)}" rx="3" fill="#27b47b"/>${gain>=0?`<rect x="${xx}" y="${by(p.value)}" width="${width}" height="${Math.abs(by(p.value)-by(p.capital))}" rx="3" fill="#96e7c2"/>`:`<rect x="${xx}" y="${zero}" width="${width}" height="${Math.abs(by(gain)-zero)}" rx="3" fill="#e88b8b"/>`}<text x="${xx+width/2}" y="235" text-anchor="middle" font-size="10" fill="#82939a">${p.date.slice(5,7)}/${p.date.slice(2,4)}</text></g>`}).join('')}${lower<0?`<text x="62" y="218" text-anchor="end" font-size="9" fill="#c16868">${short(lower)}</text>`:''}</svg>`;
 return `<div class="card"><div class="row wrap"><div><h2>Evolução dos registros</h2><span class="hint">${demo?'Histórico dos registros':'Referências históricas dos registros'}</span></div>${controls}</div><div class="row wrap chart-legend"><span><i style="background:#27b47b"></i>Capital de referência</span><span><i style="background:#96e7c2"></i>Diferença positiva</span><span><i style="background:#e88b8b"></i>Diferença negativa</span></div>${svg}<p class="chart-caption">${demo?'Trajetória simulada para apresentação. ':''}Capital = saldos iniciais a custo + aportes − retiradas. Diferença = valor de referência − capital; diferenças negativas aparecem abaixo de zero. Usa cotações dos registros, sem atualização de mercado. Não representa rentabilidade ou apuração fiscal.${points.length===120?' Exibição limitada aos primeiros 120 meses do filtro.':''}</p></div>`;
 }
 return `<div class="card"><div class="row wrap"><div><h2>Evolução dos registros</h2><span class="hint">${demo?'Trajetória ilustrativa para apresentação · dados fictícios':'Aportes separados do resultado'}</span></div><div class="badges">${controls}<span class="hint up">━ Valor de referência</span><span class="hint ambertext">┄ Capital de referência</span></div></div>${points.length?`<svg class="equity-chart" viewBox="0 0 660 220" role="img" aria-label="${demo?'Evolução fictícia para apresentação':'Valor de referência por data dos registros'}; eixo vertical ajustado"><defs><linearGradient id="equity-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#258469" stop-opacity=".22"/><stop offset="100%" stop-color="#258469" stop-opacity=".01"/></linearGradient></defs>${[0,.5,1].map(t=>`<path d="M40 ${35+t*155}H610" stroke="#edf0f2"/><text x="40" y="${28+t*155}" font-size="10" fill="#82939a">${esc(brl(max-t*span))}</text>`).join('')}<path d="${area}" fill="url(#equity-fill)"/><polyline points="${xy('capital')}" fill="none" stroke="#c49d58" stroke-width="2" stroke-dasharray="6 5"/><polyline points="${xy('value')}" fill="none" stroke="#258469" stroke-width="2.5" stroke-linejoin="round"/>${points.map(p=>`<circle cx="${x(p)}" cy="${y(p.value)}" r="3" fill="#258469" stroke="white" stroke-width="1"><title>${p.date}: patrimônio ${brl(p.value)}; capital ${brl(p.capital)}${demo?' (simulado)':''}</title></circle>`).join('')}</svg><div class="chart-bottom"><span>${esc(points[0].date.split('-').reverse().join('/'))}</span><span>${esc(end.split('-').reverse().join('/'))}</span></div>`:'<div class="empty">Adicione registros para ver a evolução.</div>'}<p class="chart-caption">${demo?'Histórico fictício com oscilações de mercado para demonstração. O ponto final corresponde ao patrimônio da carteira na data selecionada. Não altera operações, custos ou resultados.':'Referências dos lançamentos, sem atualização de mercado.'} Capital = custo inicial + aportes − retiradas. Eixo vertical ajustado.</p></div>`;
}
function audit(r){let unknown=r.rows.filter(e=>e.country==='UNKNOWN').length,zero=r.rows.filter(e=>e.type==='OPENING'&&e.costBRL===0).length,unref=r.rows.filter(e=>['BUY','SELL','CONVERT'].includes(e.type)&&!e.reference).length;return{unknown,zero,unref}}
function overview(){const r=report(),s=E.period(r,start,end),issues=E.findIssues(r);app.innerHTML=head('Sua carteira organizada','Entenda seus resultados e prepare os dados para suas obrigações fiscais.',button('＋ Registrar operação','add',true))+metrics(r)+`<div class="grid bottom"><div class="card"><div class="row wrap"><h2>De onde veio o resultado</h2>${textbtn('Ver composição','explainResult')}</div><div class="waterfall-row"><span>Vendas de ativos</span><b class="${moneyClass(s.saleResult)}">${signed(s.saleResult)}</b></div><div class="waterfall-row"><span>Câmbio, conversões e rede</span><b class="${moneyClass(s.conversion)}">${signed(s.conversion)}</b></div><div class="waterfall-row total"><strong>Resultado realizado</strong><strong class="${moneyClass(s.realized)}">${signed(s.realized)}</strong></div><p class="section-copy">Taxas já consideradas. Pagamentos de imposto aparecem na Organização fiscal.</p><div class="cash-summary"><span>Aportes <b>${brl(s.deposits)}</b></span><span>Retiradas <b>${brl(s.withdrawals)}</b></span></div>${info('Movimentações e lucro','Aportes e retiradas movimentam capital; não são lucro. A variação cambial de moedas utilizadas pode gerar resultado próprio. Abra a composição para conferir cada lançamento.')}</div><div class="card"><div class="row wrap"><h2>Conferência dos dados</h2>${pill(issues.length?'Há pendências':'Sem pendências detectadas',issues.length?'amber':'neutral')}</div><p class="sub">Revise lacunas e compare os saldos com seus extratos.</p><div class="waterfall-row"><span>Itens para revisar</span><b>${issues.length}</b></div><div class="waterfall-row"><span>Saldos comparados até ${end.split('-').reverse().join('/')}</span><b>${comparisonRows().length}</b></div><div class="actionsbar">${button('Conferir dados','checks')}${button('Organização fiscal','fiscal',true)}</div><p class="hint">Conferir quantidade não valida custo ou imposto. A comparação é manual.</p></div></div><div class="bottom">${equityChart(r)}</div>`+holdingsTable(r)}
function operations(){const r=report(),rows=E.period(r,start,end).rows.filter(e=>(typeFilter==='all'||e.type===typeFilter)&&(!query||[e.asset,e.quote,e.venue,e.reference,e.owner].join(' ').toLowerCase().includes(query.toLowerCase()))).reverse();app.innerHTML=head('Operações','Compras, vendas, conversões e movimentações em um único livro.',button('＋ Registrar operação','add',true))+`<div class="card"><div class="row wrap"><div class="actionsbar"><label style="margin:0" for="searchOps"><span class="sr-only2">Buscar operações</span><input id="searchOps" placeholder="Ativo, corretora ou referência" value="${esc(query)}"></label><label style="margin:0" for="typeFilter"><span class="sr-only2">Filtrar tipo</span><select id="typeFilter">${[['all','Todos os tipos'],...Object.entries(types)].map(([k,v])=>`<option value="${k}" ${k===typeFilter?'selected':''}>${v}</option>`).join('')}</select></label></div><span class="hint">${rows.length} lançamentos encontrados</span></div><div class="tablewrap"><table><thead><tr><th>Data / titular</th><th>Tipo / ativo</th><th>Quantidade / preço</th><th>Corretora / moeda</th><th>Valor (R$) ${info('Valor (R$)','Valor bruto em reais para negociações; custo para saldo inicial; valor movimentado para aporte, retirada ou imposto. Transferência entre contas não é uma nova aplicação.')}</th><th>Taxas BRL</th><th>Resultado ${info('Resultado','Resultado das parcelas da operação, incluindo variação cambial e taxas. Abra Ver para conferir a composição.')}</th><th>Ações</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.date.replace('T',' '))}<br><small class="hint">${esc(e.owner)}</small></td><td><span class="op-type ${e.type==='SELL'?'sell':e.type==='BUY'?'buy':''}">${types[e.type]}</span><br><b style="display:inline-block;margin-top:7px">${esc(e.asset)}</b></td><td>${qty(e.qty)} ${esc(e.asset)}<br><small class="hint">${e.price?qty(e.price)+' '+esc(e.quote)+'/un.':'—'}</small></td><td>${esc(e.venue)}<br><small class="hint">${e.type==='TRANSFER'?'→ '+esc(e.toVenue):e.quote?esc(e.quote)+' · câmbio '+n(e.fx,4):''}</small></td><td>${brl(['BUY','SELL','CONVERT'].includes(e.type)?e.grossBRL:e.type==='OPENING'?e.costBRL:e.type==='TRANSFER'?0:e.qty*e.fx)}</td><td>${brl(e.feeBRL)}</td><td class="${moneyClass(e.resultBRL)}">${e.legs.length?signed(e.resultBRL):'—'}${e.tradeResult!==null?`<br><small class="hint">Venda: ${signed(e.tradeResult)}</small>`:''}</td><td><div class="inline-actions">${textbtn('Ver','viewOp',`data-id="${esc(e.id)}"`)}${textbtn('Editar','editOp',`data-id="${esc(e.id)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Nenhum lançamento no filtro.</td></tr>'}</tbody></table></div><p class="hint">Uma venda pode ter resultado do ativo e uma operação pode gerar variação de câmbio/conversão. O detalhe separa as parcelas. Ordem: data/hora em Brasília, sequência de cadastro e identificador.</p></div><div class="export-actions bottom">${button('Exportar operações CSV','exportOps')}${button('Backup completo JSON','backup')}${button('Restaurar backup JSON','import')}</div>`;$('typeFilter').onchange=e=>{typeFilter=e.target.value;operations()};$('searchOps').onchange=e=>{query=e.target.value;operations()}}
function fiscalData(){const r=report(),s=E.period(r,start,end),year=Number(end.slice(0,4)),annual=E.annualHoldings(state.events,year,owner),issues=E.findIssues(r);return{r,s,year,annual,issues};}
function fiscalMonthly(r){const rows=[];let cursor=new Date(start+'T12:00:00Z');cursor.setUTCDate(1);while(cursor.toISOString().slice(0,10)<=end&&rows.length<1200){const month=cursor.toISOString().slice(0,7),next=new Date(cursor);next.setUTCMonth(next.getUTCMonth()+1);const last=new Date(next.getTime()-86400000).toISOString().slice(0,10);rows.push({month,...E.period(r,start>month+'-01'?start:month+'-01',end<last?end:last)});cursor=next;}return rows;}
function monthlyMarkup(r){return `<div class="tablewrap"><table><thead><tr><th>Mês</th><th>Total vendido</th><th>Custo vendido ${info('Custo vendido','Custo de aquisição das quantidades baixadas nas vendas. Pode incluir unidades consumidas em taxa no próprio ativo. Não é o custo dos saldos que você ainda possui.')}</th><th>Resultado das vendas</th><th>Câmbio e rede</th><th>Resultado total</th><th>Taxas ${info('Taxas','Já consideradas no custo ou resultado. Não desconte este total novamente.')}</th><th>Imposto pago</th></tr></thead><tbody>${fiscalMonthly(r).map(m=>{const soldCost=m.rows.filter(e=>e.type==='SELL').reduce((sum,e)=>sum+e.costBasisBRL,0);return `<tr><td>${m.month.slice(5,7)}/${m.month.slice(0,4)}</td><td>${brl(m.volume)}</td><td>${brl(soldCost)}</td><td class="${moneyClass(m.saleResult)}">${signed(m.saleResult)}</td><td class="${moneyClass(m.conversion)}">${signed(m.conversion)}</td><td class="${moneyClass(m.realized)}">${signed(m.realized)}</td><td>${brl(m.fees)}</td><td>${brl(m.tax)}</td></tr>`}).join('')}</tbody></table></div>`;}
function annualMarkup(annual,year){return `<div class="tablewrap"><table><thead><tr><th>Titular / ativo</th><th>Qtd. em 31/12/${year-1}</th><th>Custo em 31/12/${year-1}</th><th>Qtd. em 31/12/${year}</th><th>Custo em 31/12/${year}</th><th>Preço médio</th><th>Contas no fim do ano</th></tr></thead><tbody>${annual.map(h=>`<tr><td><b>${esc(h.asset)}</b><br><small>${esc(h.owner)}</small></td><td>${h.hasPrevious?qty(h.previousQty):'—'}</td><td>${h.hasPrevious?brl(h.previousCost):'Sem histórico anterior'}</td><td>${qty(h.qty)}</td><td>${brl(h.cost)}</td><td>${h.qty?brl(h.average):'—'}</td><td>${h.accounts.map(a=>`${esc(a.venue)}: ${qty(a.qty)}`).join('<br>')||'Sem saldo registrado'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhum ativo registrado para o ano.</td></tr>'}</tbody></table></div>`;}
function fiscalOperationsMarkup(rows){return `<div class="tablewrap"><table class="fiscal-operations"><thead><tr><th>Data / titular</th><th>Tipo / ativo / conta</th><th>Quantidade / preço</th><th>Câmbio ${info('Câmbio histórico','Cotação em reais por unidade da moeda usada na operação. Informada no lançamento; não é o câmbio de hoje nem uma cotação fiscal validada automaticamente.')}</th><th>Valor (R$)</th><th>Custo ${info('Custo da operação','Custo incorporado em compras/conversões ou baixado em vendas. Em saldo inicial, custo total informado. Abra o cálculo para verificar outras parcelas, como a moeda usada no pagamento.')}</th><th>Taxas (R$)</th><th>Resultado (R$)</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.date.replace('T',' '))}<br><small>${esc(e.owner)}</small></td><td><b>${types[e.type]} · ${esc(e.asset)}</b><br><small>${esc(e.venue)}${e.toVenue?' → '+esc(e.toVenue):''}</small><br><small>País: ${e.country==='BR'?'Brasil':e.country==='EX'?'Exterior':'não informado'} · Ref.: ${esc(e.reference||'não informada')}</small></td><td>${qty(e.qty)} ${esc(e.asset)}<br><small>${e.price?qty(e.price)+' '+esc(e.quote)+'/un.':'—'}</small></td><td>${['OPENING','TRANSFER'].includes(e.type)?'—':n(e.fx,4)+' / '+esc(['BUY','SELL','CONVERT'].includes(e.type)?e.quote:e.asset)}</td><td>${brl(['BUY','SELL','CONVERT'].includes(e.type)?e.grossBRL:e.type==='OPENING'?e.costBRL:e.type==='TRANSFER'?0:e.qty*e.fx)}</td><td>${['BUY','SELL','CONVERT'].includes(e.type)?brl(e.costBasisBRL):e.type==='OPENING'?brl(e.costBRL):'—'}</td><td>${brl(e.feeBRL)}${e.feeQty?`<br><small>${qty(e.feeQty)} ${esc(e.feeCurrency)} · câmbio ${n(e.feeFx,4)}</small>`:''}</td><td class="${moneyClass(e.resultBRL)}">${e.legs.length?signed(e.resultBRL):'—'}</td><td>${textbtn('Ver cálculo','viewOp',`data-id="${esc(e.id)}"`)}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Nenhuma operação no período.</td></tr>'}</tbody></table></div>`;}
function taxPaymentsMarkup(rows){const taxes=rows.filter(e=>e.type==='TAX');return `<div class="tablewrap"><table><thead><tr><th>Data do pagamento</th><th>Titular</th><th>Mês de referência</th><th>Valor (R$)</th><th>Origem</th><th>Comprovante / anotação</th></tr></thead><tbody>${taxes.map(e=>`<tr><td>${esc(e.date.slice(0,10))}</td><td>${esc(e.owner)}</td><td>${esc(e.taxPeriod||'Não informado')}</td><td>${brl(e.qty*e.fx)}</td><td>${e.taxSource==='portfolio'?'Saldo da carteira':'Fora da carteira'}</td><td>${esc(e.reference||'Não informado')}<br><small>${esc(e.notes)}</small></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum pagamento de imposto cadastrado neste período.</td></tr>'}</tbody></table></div>`;}
function fiscal(){const {r,s,year,annual,issues}=fiscalData(),cost=s.rows.filter(e=>e.type==='SELL').reduce((sum,e)=>sum+e.costBasisBRL,0);const years=[...new Set([year,...state.events.map(e=>Number(e.date.slice(0,4)))])].sort((a,b)=>b-a);app.innerHTML=head('Organização fiscal','Seus registros compilados para conferir e compartilhar com o contador.',button('Baixar relatório','fiscalReport',true))+`<div class="fiscal-intro"><div><b>Organização, do lançamento ao fechamento.</b><p>Os valores seguem seus registros. O enquadramento e a apuração do imposto ficam com você e seu contador.</p></div><label for="fiscalYear">Ver ano completo<select id="fiscalYear">${years.map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><button class="btn" data-action="fullYear">Aplicar ano</button></div><div class="numbers-row fiscal-totals">${[['Total vendido',brl(s.volume),'Valor bruto das vendas no período, antes das taxas. Não é lucro.'],['Custo vendido',brl(cost),'Custo das quantidades baixadas nas vendas, calculado com todo o histórico anterior.'],['Resultado realizado',signed(s.realized),'Resultado das vendas mais câmbio, conversões e rede. Taxas já consideradas; pagamentos de imposto não descontados. Não é imposto devido.'],['Taxas',brl(s.fees),'Total informativo de taxas em reais já incluídas nos custos ou resultados.'],['Imposto pago',brl(s.tax),'Pagamentos cadastrados manualmente, pela data em que foram pagos. Podem se referir a outro mês. Não é um cálculo do imposto devido.']].map(([l,v,h])=>`<div class="number-small"><span>${l} ${info(l,h)}</span><strong>${v}</strong></div>`).join('')}</div><div class="period-caption">Compilado de ${start.split('-').reverse().join('/')} a ${end.split('-').reverse().join('/')} · ${esc(owner==='all'?'Todos os titulares, com custos separados':owner)}</div><div class="card"><div class="row wrap"><div><h2>Resumo mensal</h2><p class="section-copy">Vendas, custos e resultados por mês. Taxas já incluídas nos cálculos.</p></div>${textbtn('Exportar mensal CSV','exportFiscal')}</div>${monthlyMarkup(r)}</div><div class="card bottom"><div class="row wrap"><div><h2>Saldos anuais a custo de aquisição</h2><p class="section-copy">Comparação de 31/12/${year-1} com 31/12/${year}, pelo histórico cadastrado do ano ${year}. Ano em andamento: prévia sujeita a novos lançamentos. Não usa preços de mercado.</p></div>${textbtn('Exportar anual CSV','exportAnnual')}</div>${annualMarkup(annual,year)}<p class="section-copy">“Sem histórico anterior” indica ausência de registros até a data anterior, não comprova saldo zero. Moedas de reserva aparecem junto dos ativos; confira a classificação com seu contador.</p></div><div class="card bottom"><div class="row wrap"><div><h2>Operações do período</h2><p class="section-copy">Quantidade, preço, câmbio, custos e resultado. Abra o cálculo para conferir cada parcela.</p></div>${textbtn('Exportar operações CSV','exportOps')}</div>${fiscalOperationsMarkup(s.rows)}</div><div class="card bottom"><h2>Pagamentos de imposto registrados</h2><p class="section-copy">Valores já pagos e informados por você. Não são impostos calculados pelo Lastro.</p>${taxPaymentsMarkup(s.rows)}</div><div class="fiscal-footer"><div><h2>Antes de usar o compilado</h2><p>${issues.length} itens de cadastro para revisar até ${end.split('-').reverse().join('/')}. Saldo coincidente não valida custo ou enquadramento fiscal.</p><p>O Lastro organiza seus dados; seu contador valida o enquadramento e a apuração. Sem emissão de DARF ou entrega de declarações.</p></div>${button('Conferir pendências','checks')}</div>`;}
function exportAnnual(){const {year,annual}=fiscalData();download('lastro-saldos-anuais-'+year+'.csv',E.csv(annual.map(h=>({ano_calendario:year,titular:h.owner,ativo:h.asset,data_anterior:h.previousDate,historico_anterior:h.hasPrevious?'Registrado':'Sem histórico anterior',quantidade_anterior:h.hasPrevious?h.previousQty:'',custo_anterior_BRL:h.hasPrevious?h.previousCost:'',data_final:h.closingDate,quantidade_final:h.qty,custo_aquisicao_final_BRL:h.cost,preco_medio_final_BRL:h.average,contas_quantidades:JSON.stringify(h.accounts)}))),'text/csv;charset=utf-8');}
function exportFiscalReport(){const {r,s,year,annual,issues}=fiscalData();const content=`<h1>Lastro · Organização fiscal</h1><p>Período: ${esc(start)} a ${esc(end)} · Titular: ${esc(owner==='all'?'Todos, com custos separados':owner)}</p><p>Compilado dos registros informados. Não calcula imposto devido nem substitui contador. Taxas já consideradas nos resultados.</p><h2>Resumo do período</h2><p>Total vendido: ${brl(s.volume)} · Resultado realizado: ${signed(s.realized)} · Taxas: ${brl(s.fees)} · Imposto pago registrado: ${brl(s.tax)}</p><h2>Resumo mensal</h2>${monthlyMarkup(r)}<h2>Saldos anuais a custo de aquisição · ${year}</h2><p>Histórico completo até 31/12/${year}, independente do mês inicial do filtro. Ausência de histórico anterior não comprova saldo zero. Valores a custo, não a mercado. Para ano em andamento, é uma prévia sujeita a novos lançamentos.</p>${annualMarkup(annual,year)}<h2>Operações do período</h2>${fiscalOperationsMarkup(s.rows)}<h2>Pagamentos de imposto registrados</h2>${taxPaymentsMarkup(s.rows)}<h2>Pendências de cadastro até ${esc(end)}</h2><ul>${issues.map(i=>{const e=r.rows.find(e=>e.id===i.id);return `<li>${esc(e.owner)} · ${esc(e.date)} · ${esc(e.asset)} · ${esc(e.reference||e.id)}: ${esc(i.label)} — ${esc(i.help)}</li>`}).join('')||'<li>Nenhuma pendência detectada nas verificações disponíveis. Isso não certifica completude ou correção fiscal.</li>'}</ul><p>Exportado em ${esc(new Date().toLocaleString('pt-BR',{timeZone:'America/Fortaleza'}))}. Os valores dependem da completude dos lançamentos e das cotações históricas informadas. Guarde documentos e comprovantes.</p>`;const printable=content.replace(/<button\b[^>]*>[\s\S]*?<\/button>/g,'');download('lastro-organizacao-fiscal-'+end+'.html',`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lastro · Organização fiscal</title><style>body{font:14px/1.5 system-ui,sans-serif;color:#17383a;margin:32px}h1{font-size:26px}h2{font-size:18px;margin-top:30px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:8px;text-align:left;border-bottom:1px solid #ddd;vertical-align:top}th{background:#eff6f3}small{color:#526c70}.tablewrap{overflow:auto}@media print{body{margin:12mm;font-size:11px}table{font-size:9px}tr{break-inside:avoid}h2{break-after:avoid}}</style><body>${printable}</body></html>`,'text/html;charset=utf-8');}

function detail(){const r=report(),h=positions(r).find(x=>pk(x)===selected);if(!h){go('overview');return;}const rows=r.rows.filter(e=>e.owner===h.owner&&(e.asset===h.asset||e.quote===h.asset||e.feeCurrency===h.asset));app.innerHTML=textbtn('← Visão geral','overview')+head(h.asset+' · '+(catalog[h.asset]?.name||h.asset),esc(h.owner),button('＋ Registrar operação','addForAsset',true,`data-asset="${esc(h.asset)}" data-owner="${esc(h.owner)}"`))+`<div class="numbers-row">${[['Quantidade',qty(h.qty)],['Preço médio',brl(h.average)],['Custo do saldo',brl(h.cost)],['Valor de referência',brl(h.value)]].map(([l,v])=>`<div class="number-small"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="card"><div class="row wrap"><h2>Onde está o saldo</h2>${textbtn('Comparar com extrato','checks')}</div>${Object.entries(r.custody).filter(([k,q])=>k.startsWith(h.owner+'|')&&k.endsWith('|'+h.asset)&&q>E.EPS).map(([k,q])=>`<div class="waterfall-row"><span>${esc(k.slice(h.owner.length+1,-h.asset.length-1))}</span><b>${qty(q)} ${esc(h.asset)}</b></div>`).join('')}<p class="hint">Custo médio consolidado por titular, mesmo com várias contas. O valor de referência usa a última cotação registrada; não é cotação de mercado.</p></div><div class="card bottom"><h2>Histórico que explica este saldo</h2><div class="tablewrap"><table><thead><tr><th>Data</th><th>Operação</th><th>Conta</th><th>Quantidade negociada</th><th>Resultado da operação</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.date.replace('T',' '))}</td><td>${types[e.type]}</td><td>${esc(e.venue)}</td><td>${qty(e.qty)} ${esc(e.asset)}</td><td class="${moneyClass(e.resultBRL)}">${e.legs.length?signed(e.resultBRL):'—'}</td><td>${textbtn('Ver cálculo','viewOp',`data-id="${esc(e.id)}"`)}</td></tr>`).join('')}</tbody></table></div></div>`}
function comparisonRows(){return(state.reconciliations||[]).filter(c=>(owner==='all'||c.owner===owner)&&c.date<=end).map(c=>E.compareBalance(state.events,c)).sort((a,b)=>b.date.localeCompare(a.date));}
function explainResult(){const s=E.period(report(),start,end),rows=s.rows.filter(e=>e.legs.length);show('De onde veio o resultado',`<div class="result-split"><div>Vendas<b>${signed(s.saleResult)}</b></div><div>Câmbio e outros<b>${signed(s.conversion)}</b></div><div>Total realizado<b>${signed(s.realized)}</b></div></div><p>Taxas já incluídas. Pagamentos de imposto ficam separados.</p><div class="tablewrap"><table><thead><tr><th>Data / titular</th><th>Operação</th><th>Venda</th><th>Câmbio e outros</th><th>Total</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.date.slice(0,10))}<br>${esc(e.owner)}</td><td>${types[e.type]} · ${esc(e.asset)}</td><td>${e.tradeResult===null?'—':signed(e.tradeResult)}</td><td>${signed(e.conversionResult+e.feeResult)}</td><td>${signed(e.resultBRL)}</td><td>${textbtn('Ver cálculo','resultOp',`data-id="${esc(e.id)}"`)}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum resultado no período.</td></tr>'}</tbody></table></div>`,()=>modal.close());$('form').querySelector('button[type=submit]').textContent='Fechar';}
function checks(){const r=report(),issues=E.findIssues(r),comparisons=comparisonRows();app.innerHTML=head('Confira antes de confiar','Encontre lacunas e compare os saldos com seus documentos.',button('＋ Comparar saldo','compare',true))+`<div class="numbers-row">${[['Itens para revisar',issues.length],['Comparações registradas',comparisons.length],['Saldos com diferença',comparisons.filter(c=>!c.matches).length]].map(([l,v])=>`<div class="number-small"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="card"><div class="row wrap"><h2>Saldos do extrato ${info('Comparação de saldos','Compare o saldo total de cada ativo por conta no fim do dia informado. O valor do extrato é digitado por você; o Lastro não o obtém da corretora. Comparações são recalculadas após correções no histórico. Coincidir quantidade não comprova preço médio ou completude.')}</h2>${textbtn('Exportar comparações','exportChecks')}</div><div class="tablewrap"><table><thead><tr><th>Data / titular</th><th>Conta / ativo</th><th>No Lastro</th><th>No extrato</th><th>Diferença ${info('Diferença de quantidade','Saldo calculado pelo Lastro menos o saldo informado do extrato. Uma diferença pede investigação; o app não cria ajustes automáticos.')}</th><th>Conferência</th><th>Documento</th></tr></thead><tbody>${comparisons.map(c=>`<tr><td>${esc(c.date)}<br><small>${esc(c.owner)}</small></td><td>${esc(c.venue)} · ${esc(c.asset)}</td><td>${qty(c.book)}</td><td>${qty(c.qty)}</td><td class="${c.matches?'':'negative'}">${qty(c.difference)}</td><td>${pill(c.matches?'Quantidade coincide':'Revisar diferença',c.matches?'neutral':'amber')}</td><td>${esc(c.reference)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Ainda não comparado. Pegue um extrato e informe um saldo para começar.</td></tr>'}</tbody></table></div><p class="hint">As comparações cobrem somente as contas, ativos e datas informados. Não validam impostos ou custos. Use o saldo total da conta, incluindo valores bloqueados em ordens, não apenas o disponível para negociar.</p></div><div class="card bottom"><h2>O que precisa de revisão ${info('Escopo das verificações','Checagens de cadastro sobre todo o histórico do titular até a data Até. Não detectam todas as operações ausentes ou incorretas. Nenhum item é corrigido ou excluído automaticamente.')}</h2><div class="tablewrap"><table><thead><tr><th>O que conferir</th><th>Data</th><th>Titular / conta</th><th>Ativo</th><th></th></tr></thead><tbody>${issues.map(issue=>{const e=r.rows.find(x=>x.id===issue.id);return `<tr><td>${esc(issue.label)} <br><small class="row-help">${esc(issue.help)}</small></td><td>${esc(e.date.slice(0,10))}</td><td>${esc(e.owner)}<br><small>${esc(e.venue)}</small></td><td>${esc(e.asset)}</td><td>${textbtn('Revisar lançamento','fixIssue',`data-id="${esc(e.id)}"`)}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Nenhuma pendência detectada nessas verificações. Compare também os saldos com seus extratos.</td></tr>'}</tbody></table></div></div>`;}
function addComparison(){show('Comparar com meu extrato',`<p>Informe o saldo total do ativo no fim do dia. Esta comparação não altera suas operações. Repetir titular, conta, ativo e data atualiza a comparação anterior.</p><div class="form-grid">${select('compareOwner','Titular',state.owners.map(o=>[o,o]),owner==='all'?state.owners[0]:owner)}${input('compareDate','Data do saldo',end,'date','required')}${input('compareVenue','Conta / corretora',state.events.find(e=>owner==='all'||e.owner===owner)?.venue||'','text','required maxlength="80"')}${select('compareAsset','Ativo',ASSETS.map(a=>[a,a]),'BTC')}${input('compareQty','Saldo total no extrato',0,'number','required min="0" max="1000000000000" step="any"')}${input('compareReference','Referência do documento','','text','required maxlength="120"')}</div>`,f=>{const c={owner:String(f.get('compareOwner')),date:String(f.get('compareDate')),venue:String(f.get('compareVenue')).trim(),asset:String(f.get('compareAsset')),qty:Number(f.get('compareQty')),reference:String(f.get('compareReference')).trim()};if(!state.owners.includes(c.owner)||!c.reference)throw Error('Informe titular e referência do extrato.');const result=E.compareBalance(state.events,c);state.reconciliations=state.reconciliations||[];const index=state.reconciliations.findIndex(x=>x.owner===c.owner&&x.venue===c.venue&&x.asset===c.asset&&x.date===c.date);if(index<0)state.reconciliations.push(c);else state.reconciliations[index]=c;persist();modal.close();go('checks');toast(result.matches?'Quantidade coincide com o saldo informado.':'Diferença encontrada. Confira os lançamentos; nenhum ajuste foi feito.');});}
function exportChecks(){download('lastro-comparacoes-'+end+'.csv',E.csv(comparisonRows().map(c=>({data:c.date,titular:c.owner,conta:c.venue,ativo:c.asset,saldo_lastro:c.book,saldo_extrato:c.qty,diferenca:c.difference,quantidade_coincide:c.matches?'Sim':'Não',referencia:c.reference}))),'text/csv;charset=utf-8');}

function settings(){app.innerHTML=head('Dados e backup','Titulares separados e backup do livro completo.')+`<div class="grid"><div class="card"><div class="row"><h2>Titulares</h2>${textbtn('＋ Adicionar','addOwner')}</div>${state.owners.map(o=>`<div class="plan-line"><b>${esc(o)}</b><span class="hint">Custo médio independente</span></div>`).join('')}<p class="hint">A visão família soma valores, mas não mistura o custo dos titulares.</p></div><div class="card"><h2>Backup e recuperação</h2><p>Dados salvos neste navegador. Exporte um backup.</p><div class="export-actions">${button('Exportar backup JSON','backup',true)}${button('Restaurar JSON','import')}</div><p class="hint">Restauração substitui a v3 após validação e confirmação. Não é importação de corretora.</p></div></div><div class="fiscal-warning"><strong>Protótipo com exemplos fictícios.</strong>Para começar seu próprio livro, use a opção abaixo. O custo de saldos anteriores precisa ser conhecido e informado; saldo inicial não é lucro nem aporte novo.</div><div class="export-actions">${button('Começar livro vazio','empty')}${button('Restaurar exemplos fictícios','reset')}</div>`}
function render(){document.querySelector('.banner-demo span').textContent=state.events.some(e=>/^demo\d+$/.test(e.id))?'Exemplos fictícios · valores em reais · histórico contínuo':'Registro manual · valores em reais · histórico contínuo';const nav=[['overview','◫','Visão geral'],['operations','≡','Operações'],['checks','✓','Conferência'],['fiscal','▤','Organização fiscal'],['settings','⚙','Dados e backup']];$('nav').innerHTML=nav.map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}">${i} &nbsp; ${t}</button>`).join('');$('crumb').textContent=page==='detail'?'Detalhe da posição':nav.find(x=>x[0]===page)[2];$('filters').innerHTML=`<label for="ownerFilter">Titular<select id="ownerFilter"><option value="all">Todos os titulares</option>${state.owners.map(o=>`<option ${owner===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label><label for="dateStart">De<input id="dateStart" type="date" value="${start}" required></label><label for="dateEnd">Até<input id="dateEnd" type="date" value="${end}" required></label><span class="filter-note">Resultados: período selecionado. Saldos: acumulados até a data final.</span>`;for(let id of ['ownerFilter','dateStart','dateEnd'])$(id).onchange=()=>{let s=$('dateStart').value,e=$('dateEnd').value;if(!s||!e||s>e){toast('Informe um intervalo de datas válido.');render();return}start=s;end=e;owner=$('ownerFilter').value;render()};({overview,operations,checks,fiscal,settings,detail}[page])()}
function show(title,fields,handler){$('modalTitle').textContent=title;$('fields').innerHTML=fields;$('formError').textContent='';form.oninput=null;form.onchange=null;form.querySelector('button[type=submit]').textContent='Salvar';form.onsubmit=e=>{e.preventDefault();try{handler(new FormData(form))}catch(err){$('formError').textContent=err.message}};modal.showModal()}
const fieldHelp={
 country:['País da instituição','Informe Brasil ou exterior conforme os documentos da corretora ou instituição. Essa informação ajuda a organizar a conferência fiscal.'],
 costBRL:['Custo total (R$)','Custo de aquisição do saldo anterior, incluindo taxas. Não é seu valor de mercado hoje. Use zero apenas se o custo for comprovadamente zero.'],
 fx:['Cotação em reais','Valor em reais de 1 unidade da moeda usada na operação, na data em que ela ocorreu. Exemplo: 1 USDC = R$ 5,20 → informe 5,20. Para BRL, o valor é 1.'],
 feeFx:['Cotação da taxa (R$)','Valor em reais de 1 unidade da moeda da taxa na data da operação. Preenchido automaticamente quando a taxa é na moeda ou ativo negociado; para outro token, informe a cotação histórica.'],
 feeQty:['Valor da taxa','Quantidade paga na moeda da taxa. Exemplo: taxa de 2 USDC → informe 2 e selecione USDC.'],
 taxPeriod:['Mês de referência','Mês das operações a que o imposto se refere. Pode ser diferente da data em que você pagou. Os totais da tela usam a data do pagamento.'],
 taxSource:['De onde saiu o pagamento','Fora da carteira apenas registra o pagamento. Debitar do saldo reduz a moeda na conta selecionada. O imposto precisa ter sido apurado e pago por você.'],
 reference:['Ordem ou comprovante','Identificador da ordem, transferência ou pagamento para facilitar a conferência com a corretora e seus documentos.']
};
function fieldLabel(id,label){const help=fieldHelp[id];return help?esc(help[0]):label}
const input=(id,label,value,type='text',extra='')=>`<div><label for="${id}">${fieldLabel(id,label)}</label>${fieldHelp[id]?info(fieldHelp[id][0],fieldHelp[id][1]):''}<input id="${id}" name="${id}" type="${type}" value="${esc(value??'')}" ${extra}></div>`;
const select=(id,label,options,value)=>`<div><label for="${id}">${fieldLabel(id,label)}</label>${fieldHelp[id]?info(fieldHelp[id][0],fieldHelp[id][1]):''}<select id="${id}" name="${id}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
let editing=null,opDefault={};
function opFields(d){const t=d.type,trade=['BUY','SELL','CONVERT'].includes(t),moving=['DEPOSIT','WITHDRAW','TAX'].includes(t),initial=t==='OPENING',transfer=t==='TRANSFER';return `<div class="form-grid three">${select('type','Tipo de lançamento',Object.entries(types),t)}${select('opOwner','Titular',state.owners.map(o=>[o,o]),d.owner)}${input('date','Data / hora · Brasília',d.date,'datetime-local','required')}</div><div class="form-grid three">${input('venue','Corretora / conta / carteira',d.venue,'text','required maxlength="80"')}${select('country','Localização da instituição',[['UNKNOWN','Não informado'],['BR','Brasil'],['EX','Exterior']],d.country)}${select('asset',trade?(t==='CONVERT'?'Ativo recebido':'Ativo negociado'):'Ativo / moeda',(moving?FIAT:ASSETS).map(a=>[a,a]),moving&&!FIAT.includes(d.asset)?'BRL':d.asset)}</div><div class="form-grid three">${input('qty',trade&&t==='CONVERT'?'Quantidade recebida':'Quantidade',d.qty,'number','required min="0.00000001" max="1000000000000" step="any"')}${trade?input('price',t==='CONVERT'?'Unidades pagas por ativo recebido':'Preço unitário na moeda abaixo',d.price,'number','required min="0.00000001" max="1000000000000" step="any"')+select('quote',t==='CONVERT'?'Moeda / ativo entregue':'Moeda de negociação',ASSETS.map(a=>[a,a]),d.quote):initial?input('costBRL','Custo histórico total em BRL',d.costBRL,'number','required min="0" max="1000000000000000000" step="any"'):transfer?input('toVenue','Carteira / conta de destino',d.toVenue||'','text','required maxlength="80"'):''}${!initial&&!transfer?input('fx',trade?'1 unidade da moeda de negociação em BRL':'1 unidade da moeda em BRL',d.fx,'number','required min="0.00000001" max="1000000000" step="any"'):''}</div>${transfer?'<p class="hint">Transferência entre contas do mesmo titular: move custódia sem venda. Se a origem ou destino for de outra pessoa, não use este tipo.</p>':''}${trade||transfer?`<details ${d.feeQty?'open':''}><summary>Taxas da operação</summary><div class="form-grid three">${input('feeQty','Quantidade da taxa',d.feeQty||0,'number','required min="0" max="1000000000000" step="any"')}${select('feeCurrency','Moeda da taxa',ASSETS.map(a=>[a,a]),d.feeCurrency||d.quote)}${input('feeFx','1 unidade da moeda da taxa em BRL',d.feeFx||1,'number','required min="0.00000001" step="any"')}</div><p class="hint">Taxa no ativo ou na moeda negociada: câmbio automático. Em outro token, informe a cotação histórica e registre o saldo anterior.</p></details>`:''}${t==='TAX'?`<div class="form-grid">${input('taxPeriod','Competência do imposto',d.taxPeriod||'','month')}${select('taxSource','Origem do pagamento',[['external','Fora da carteira (só registro)'],['portfolio','Debitar do saldo desta conta']],d.taxSource||'external')}</div><p class="hint">Registre um pagamento já realizado. A apuração é feita por você ou seu contador.</p>`:''}<div class="form-grid">${input('reference','ID da ordem / comprovante',d.reference||'','text','maxlength="100"')}${input('notes','Observação / origem do custo',d.notes||'','text','maxlength="500"')}</div><div id="opPreview" class="record-help"></div>${initial?'<p class="hint">Custo zero só deve ser usado quando efetivamente conhecido como zero. Inclua a origem/documentação no campo observação. Saldos iniciais ficam separados dos aportes novos.</p>':''}${trade?'<p class="hint">Em compras/vendas, quantidade × preço forma o valor bruto. Conversões são registradas uma única vez, com perna de saída e de entrada derivadas automaticamente.</p>':''}`}
function eventFromForm(f,source){const d={...source,id:editing?.id||'op'+Date.now(),sequence:editing?.sequence||Math.max(0,...state.events.map(e=>e.sequence||0))+1,type:String(f.get('type')),owner:String(f.get('opOwner')),date:String(f.get('date')),venue:String(f.get('venue')||'').trim(),country:String(f.get('country')),asset:String(f.get('asset')),qty:Number(f.get('qty')),price:Number(f.get('price')||0),quote:String(f.get('quote')||'BRL'),fx:Number(f.get('fx')||1),feeQty:Number(f.get('feeQty')||0),feeCurrency:String(f.get('feeCurrency')||'BRL'),feeFx:Number(f.get('feeFx')||1),reference:String(f.get('reference')||'').trim(),notes:String(f.get('notes')||'').trim(),costBRL:Number(f.get('costBRL')||0),toVenue:String(f.get('toVenue')||'').trim(),taxPeriod:String(f.get('taxPeriod')||''),taxSource:String(f.get('taxSource')||'external')};if(['BUY','SELL','CONVERT'].includes(d.type)){if(d.quote==='BRL')d.fx=1;if(d.feeCurrency===d.quote)d.feeFx=d.fx;else if(d.feeCurrency===d.asset)d.feeFx=d.price*d.fx;else if(d.feeCurrency==='BRL')d.feeFx=1;}else if(d.feeCurrency==='BRL')d.feeFx=1;if(['DEPOSIT','WITHDRAW','TAX'].includes(d.type)&&d.asset==='BRL')d.fx=1;return d}
function addOperation(id=null,defaults={}){editing=id?state.events.find(e=>e.id===id):null;let d=editing?cl(editing):{type:'BUY',owner:owner==='all'?state.owners[0]:owner,date:new Date().toLocaleString('sv-SE',{timeZone:'America/Fortaleza'}).slice(0,16).replace(' ','T'),venue:'',country:'UNKNOWN',asset:'BTC',qty:'',price:'',quote:'USDC',fx:'',feeQty:0,feeCurrency:'USDC',feeFx:5.2,...defaults};opDefault=d;
 show(editing?'Editar lançamento':'Registrar operação',opFields(d),f=>{const e=eventFromForm(f,d);E.validate(e);if(e.reference&&state.events.some(x=>x.id!==e.id&&x.owner===e.owner&&x.venue===e.venue&&x.reference===e.reference))throw Error('Referência já cadastrada para este titular e conta. Confira possível duplicidade.');const candidate=state.events.filter(x=>x.id!==e.id).concat(e);E.replay(candidate);state.events=candidate;persist();modal.close();render();toast('Livro recalculado. Preço médio, resultado e saldos atualizados.');});wireOp(d)
}
function wireOp(d){const update=()=>{try{const e=eventFromForm(new FormData(form),d),trade=['BUY','SELL','CONVERT'].includes(e.type),fee=e.feeQty*e.feeFx;let gross=trade?e.qty*e.price*e.fx:e.type==='OPENING'?e.costBRL:e.qty*e.fx;let candidate=state.events.filter(x=>x.id!==e.id).concat(e);let r=E.replay(candidate),row=r.rows.find(x=>x.id===e.id);$('opPreview').innerHTML=`<div class="row wrap"><span>Valor da operação: <b>${brl(gross)}</b></span><span>Taxas: <b>${brl(fee)}</b></span></div>${row.legs.length?`<p>Lucro/prejuízo: <b class="${moneyClass(row.resultBRL)}">${signed(row.resultBRL)}</b> · ${row.tradeResult!==null?'venda '+signed(row.tradeResult)+' · ':''}câmbio e outros resultados ${signed(row.conversionResult+row.feeResult)}</p>`:''}<span class="hint">${e.type==='TRANSFER'?'Movimenta custódia, preserva o preço médio; a taxa reduz o resultado.':e.type==='OPENING'?'Estabelece custo e quantidade anteriores, sem gerar lucro.':'Prévia válida para todo o histórico, inclusive operações posteriores.'}</span>`;if($('fx')){let auto=trade?e.quote==='BRL':e.asset==='BRL';$('fx').readOnly=auto;if(auto)$('fx').value='1'}if($('feeFx')){let auto=e.feeCurrency==='BRL'||(trade&&[e.asset,e.quote].includes(e.feeCurrency));$('feeFx').readOnly=auto;if(auto)$('feeFx').value=String(e.feeFx)}}catch(err){$('opPreview').innerHTML=`<span class="ambertext">${esc(err.message)}</span>`}};
 $('type').onchange=()=>{let current=eventFromForm(new FormData(form),d);current.type=$('type').value;if(['DEPOSIT','WITHDRAW','TAX'].includes(current.type)){current.asset='BRL';current.qty=100;current.fx=1;current.feeQty=0}else if(current.type==='OPENING'){current.costBRL=0;current.feeQty=0}else if(['BUY','SELL','CONVERT'].includes(current.type)&&current.asset==='BRL'){current.asset='BTC';current.quote='USDC';current.qty='';current.price='';current.fx=''}if(current.type==='TRANSFER')current.toVenue='Carteira própria';$('fields').innerHTML=opFields(current);wireOp(current)};for(let id of ['asset','quote','feeCurrency'])if($(id))$(id).addEventListener('change',()=>{if(id==='quote'&&$('fx')){$('fx').value=$('quote').value==='BRL'?'1':''}if(id==='asset'&&['DEPOSIT','WITHDRAW','TAX'].includes($('type').value)&&$('fx'))$('fx').value=$('asset').value==='BRL'?'1':'';update()});form.oninput=update;form.onchange=update;update()}
function viewOperation(id){const r=E.replay(state.events),e=r.rows.find(x=>x.id===id);if(!e)return;show(types[e.type]+' · '+e.asset,`<div class="operation-line"><b>${esc(e.owner)} · ${esc(e.date.replace('T',' '))}</b><p>${esc(e.venue)} · instituição: ${e.country==='UNKNOWN'?'não informada':e.country==='BR'?'Brasil':'Exterior'} · sequência ${e.sequence}</p><p>Referência: ${esc(e.reference||'não informada')}</p></div><div class="result-split"><div>Quantidade<b>${qty(e.qty)} ${esc(e.asset)}</b></div><div>Custo da operação<b>${brl(e.costBasisBRL)}</b></div><div>Taxas das operações<b>${brl(e.feeBRL)}</b></div><div>Resultado total<b class="${moneyClass(e.resultBRL)}">${signed(e.resultBRL)}</b></div></div>${e.legs.map(l=>`<div class="operation-line"><b>${esc(l.asset)} · ${esc(({sale:'Venda do ativo',funding:'Moeda utilizada na compra',conversion:'Ativo entregue na conversão',fee:'Pagamento de taxa','withdraw-fx':'Câmbio na retirada','tax-fx':'Câmbio no pagamento','network-expense':'Despesa de rede' })[l.category]||l.category)}</b><p>Quantidade ${qty(l.qty)} · valor ${brl(l.valueBRL)} · custo baixado ${brl(l.costBRL)} · resultado ${signed(l.resultBRL)}</p></div>`).join('')}<p class="hint">${e.type==='OPENING'?'Custo unitário histórico informado: '+brl(e.costBRL/e.qty)+'. Referência cadastral:':'Cotação histórica: '+n(e.fx,6)+' BRL por unidade de'} ${esc(['BUY','SELL','CONVERT'].includes(e.type)?e.quote:e.asset)}. Taxas não devem ser subtraídas novamente dos resultados exibidos.</p>${e.type==='TAX'?`<p>Competência: ${esc(e.taxPeriod||'não informada')} · origem: ${e.taxSource==='portfolio'?'saldo da conta':'fora da carteira'}</p>`:''}<p>${esc(e.notes)}</p><div class="actionsbar">${textbtn('Editar lançamento','editFromDetail',`data-id="${esc(e.id)}"`)}${textbtn('Excluir lançamento','deleteOp',`data-id="${esc(e.id)}"`)}</div>`,()=>modal.close())}
function removeOp(id){const e=state.events.find(x=>x.id===id);if(!e)return;show('Excluir lançamento?',`<p>${types[e.type]} de ${qty(e.qty)} ${esc(e.asset)}, em ${esc(e.date)}.</p><p>Todo o livro será reprocessado. A exclusão será recusada se deixar alguma operação posterior sem saldo. Exporte um backup antes se quiser preservar esta versão.</p>`,()=>{const events=state.events.filter(x=>x.id!==id);E.replay(events);state.events=events;persist();modal.close();render();toast('Lançamento excluído e histórico recalculado.');})}
function download(name,data,mime){const url=URL.createObjectURL(new Blob([data],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportOps(){let rows=E.period(report(),start,end).rows.map(e=>({id:e.id,sequencia:e.sequence,data_brasilia:e.date,titular:e.owner,instituicao:e.venue,localizacao:e.country,tipo:types[e.type],ativo:e.asset,quantidade:e.qty,preco_unitario:e.price,moeda_negociacao:e.quote,cotacao_BRL:['OPENING','TRANSFER'].includes(e.type)?'':e.fx,bruto_BRL:e.grossBRL,liquido_BRL:e.netBRL,custo_baixado_ou_incorporado_BRL:e.costBasisBRL,saldo_inicial_custo_BRL:e.type==='OPENING'?e.costBRL:'',valor_movimentacao_BRL:['DEPOSIT','WITHDRAW','TAX'].includes(e.type)?e.qty*e.fx:'',taxa_quantidade:e.feeQty,taxa_moeda:e.feeCurrency,taxa_cotacao_BRL:e.feeFx,taxa_valor_BRL:e.feeBRL,resultado_venda_BRL:e.tradeResult??'',resultado_conversao_cambio_BRL:e.conversionResult,resultado_taxas_rede_BRL:e.feeResult,resultado_total_BRL:e.resultBRL,quantidade_final_ativo:e.inventoryAfter,PM_final_BRL:e.avgAfter,transferencia_destino:e.toVenue||'',competencia_imposto:e.taxPeriod||'',origem_pagamento:e.taxSource||'',referencia:e.reference,observacao:e.notes,pernas_json:JSON.stringify(e.legs)}));download('lastro-operacoes-'+end+'.csv',E.csv(rows),'text/csv;charset=utf-8')}
function exportHoldings(){let rows=positions().map(h=>({data_final:end,titular:h.owner,ativo:h.asset,quantidade:h.qty,PM_BRL:h.average,custo_aberto_BRL:h.cost,preco_referencia_BRL:h.mark,valor_marcado_BRL:h.value,resultado_aberto_BRL:h.unrealized,fonte:'Última cotação registrada nas operações',custodia_json:JSON.stringify(Object.entries(report(h.owner).custody).filter(([k,v])=>k.endsWith('|'+h.asset)&&v>E.EPS))}));download('lastro-carteira-'+end+'.csv',E.csv(rows),'text/csv;charset=utf-8')}
function exportFiscal(){let rows=[];for(const o of owner==='all'?state.owners:[owner]){const r=report(o);for(const m of fiscalMonthly(r))rows.push({titular:o,mes:m.month,negociacoes:m.count,vendas:m.sales,vendas_com_lucro:m.wins,vendas_com_prejuizo:m.losses,vendas_neutras:m.flat,vendas_brutas_BRL:m.volume,custo_vendido_BRL:m.rows.filter(e=>e.type==='SELL').reduce((sum,e)=>sum+e.costBasisBRL,0),resultado_vendas_BRL:m.saleResult,conversoes_cambio_rede_BRL:m.conversion,resultado_realizado_BRL:m.realized,taxas_ja_consideradas_BRL:m.fees,impostos_pagos_registrados_BRL:m.tax,aportes_BRL:m.deposits,retiradas_BRL:m.withdrawals});}download('lastro-resumo-mensal-'+end+'.csv',E.csv(rows),'text/csv;charset=utf-8')}
function backup(){download('lastro-backup-v3-'+end+'.json',JSON.stringify(state,null,2),'application/json')}
function reset(empty=false){show(empty?'Começar um livro vazio?':'Restaurar exemplos fictícios?',`<p>Esta ação substitui os dados da v3 neste navegador. Exporte um backup para preservar operações e comparações de saldo. As versões anteriores permanecem separadas.</p>${empty?input('newOwner','Primeiro titular','','text','required maxlength="80"'):''}`,f=>{if(empty){let name=String(f.get('newOwner')).trim();if(!name||name.includes('|'))throw Error('Informe um nome sem o caractere |.');state={version:3,owners:[name],scenario:'mixed',events:[],plans:{},reviews:[]}}else state=cl(seed);owner='all';persist();modal.close();go('overview');toast(empty?'Livro vazio pronto. Comece por aportes ou saldos iniciais.':'Exemplos restaurados.');})}
function addOwner(){show('Adicionar titular',input('name','Nome do titular','','text','required maxlength="80"'),f=>{let name=String(f.get('name')).trim();if(!name||name.includes('|')||state.owners.some(x=>x.toLowerCase()===name.toLowerCase()))throw Error('Nome inválido ou já cadastrado. Não use |.');state.owners.push(name);persist();modal.close();render()})}
$('backupFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5e6)throw Error('Backup acima de 5 MB.');let candidate=check(JSON.parse(await file.text()));show('Restaurar backup v3?',`<p>${candidate.events.length} lançamentos e ${candidate.owners.length} titulares. O histórico passou na validação de saldos. Salvar substituirá o livro local; exporte seu backup atual antes de confirmar.</p>`,()=>{state=candidate;owner='all';persist();modal.close();go('overview');toast('Backup restaurado e livro recalculado.');})}catch(err){toast('Backup não importado: '+err.message)}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-holding],[data-action]');if(!el)return;if(el.dataset.page)return go(el.dataset.page);if(el.dataset.holding)return openHolding(el.dataset.holding);let a=el.dataset.action,id=el.dataset.id,key=el.dataset.key;switch(a){case'chartView':chartView=key;overview();break;case'overview':case'fiscal':case'checks':go(a);break;case'add':addOperation();break;case'addForAsset':addOperation(null,{asset:el.dataset.asset,owner:el.dataset.owner});break;case'viewOp':viewOperation(id);break;case'editOp':addOperation(id);break;case'editFromDetail':modal.close();addOperation(id);break;case'deleteOp':modal.close();removeOp(id);break;case'holdingDetail':openHolding(key);break;case'explainResult':explainResult();break;case'compare':addComparison();break;case'fixIssue':addOperation(id);break;case'resultOp':modal.close();viewOperation(id);break;case'exportChecks':exportChecks();break;case'exportOps':exportOps();break;case'exportHoldings':exportHoldings();break;case'exportFiscal':exportFiscal();break;case'exportAnnual':exportAnnual();break;case'fiscalReport':exportFiscalReport();break;case'fullYear':start=$('fiscalYear').value+'-01-01';end=$('fiscalYear').value+'-12-31';render();break;case'backup':backup();break;case'import':$('backupFile').click();break;case'reset':reset();break;case'empty':reset(true);break;case'addOwner':addOwner();break}});
document.addEventListener('keydown',e=>{let row=e.target.closest('[data-holding]');if(row&&['Enter',' '].includes(e.key)){e.preventDefault();openHolding(row.dataset.holding)}});
$('reset').onclick=()=>reset();$('closeModal').onclick=()=>modal.close();$('cancelModal').onclick=()=>modal.close();
installHelp();render();if(recovery)toast('Dados v3 inválidos ou indisponíveis. Exibindo exemplos; backup inválido não foi sobrescrito.');
